<?php
namespace Src\Inventario\Infrastructure\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
class RepuestoEloquentModel extends Model{use HasUuids;protected $table='repuestos';protected $fillable=['categoria_id','proveedor_id','codigo','nombre','descripcion','unidad','stock_minimo','costo_referencia','precio_venta','estado','creado_por','actualizado_por'];protected function casts():array{return['stock_actual'=>'decimal:3','stock_minimo'=>'decimal:3','costo_referencia'=>'decimal:2','precio_venta'=>'decimal:2'];}public function categoria():BelongsTo{return$this->belongsTo(CategoriaRepuestoEloquentModel::class,'categoria_id');}public function proveedor():BelongsTo{return$this->belongsTo(ProveedorEloquentModel::class,'proveedor_id');}}
